```16:39:store/db/postgres/postgres.go
type DB struct {
	db      *sql.DB
	profile *profile.Profile
}

func NewDB(profile *profile.Profile) (store.Driver, error) {
	// ...
	var driver store.Driver = &DB{
		db:      db,
		profile: profile,
	}

	// Return the DB struct
	return driver, nil
}
```

That struct is wired in from `store/db/db.go` when the configured driver is `"postgres"`.
